function geneticAlgorithm(popSize, generations, mutationRate):
    population = initializeRandom(popSize)

    for gen in 0..generations:
        // Evaluate fitness
        fitness = evaluateFitness(population)

        // Selection (tournament)
        selected = tournamentSelection(population, fitness, tournamentSize=3)

        // Crossover
        offspring = []
        for i in 0..popSize/2:
            parent1, parent2 = selectParents(selected)
            child1, child2 = crossover(parent1, parent2, rate=0.8)
            offspring.add(child1, child2)

        // Mutation
        for individual in offspring:
            if random() < mutationRate:
                mutate(individual)

        // Elitism: keep best individuals
        population = elitismMerge(population, offspring, eliteCount=2)

    return bestIndividual(population)
